        "set.el.ver_embed": "View the embed in a new tab ↗",
        "set.el.paso2_titulo": "2 · Authorized domains",
        "set.el.paso2_desc": "For security (anti-clickjacking), specify which domains can embed your quote builder. One per line or comma-separated. Wildcards accepted: <code>client.com</code>, <code>*.client.com</code>, <code>https://app.client.com</code>.",
        "set.el.status_ok": "Only domains on the list can embed your quote builder.",
        "set.el.status_warn": "Empty list: your quote builder can be embedded for display only. Approving, signing and paying open in a Cord tab, and your live publishable key won't work until you add domains.",
        "set.el.preview_titulo": "Live preview",
        "set.el.preview_desc": "This is what your embedded quote builder looks like right now — the same iframe that will load on your client's site.",
